{
  "cubeName": "sales_cube",
  "queryName": "total store sales by product category for the year 1997",
  "aggregateFunction": "sum",
  "measure": "store_sales",
  "gamma": [
    "product_dim.product_category"
  ],
  "sigma": [
    "date_dim.the_year = 1997"
  ]
}

